    private void colours(){boolean dark=host.getSharedPreferences("settings",0).getBoolean("dark_mode",false);bg=dark?0xff000000:0xfffff9f0;panel=dark?0xff211c17:0xffeee4d7;text=dark?0xfff6efe5:0xff2c2118;muted=dark?0xffc0af9b:0xff6b5948;accent=dark?0xffe89045:0xff9c3708;line=dark?0xff332a22:0xffd7c8b6;}
    private int dp(float n){return Math.round(n*host.getResources().getDisplayMetrics().density);}
    private GradientDrawable surface(int colour){GradientDrawable d=new GradientDrawable();d.setColor(colour);d.setCornerRadius(dp(16));return d;}
    private TextView label(String s,int size,int colour){TextView v=new TextView(host);v.setText(s);v.setTextSize(size);v.setTextColor(colour);return v;}
