    private Button button(String title,Runnable action){Button b=new Button(host);b.setText(title);b.setTextSize(16);b.setAllCaps(false);b.setTextColor(accent);b.setBackground(surface(panel));b.setMinHeight(dp(52));b.setOnClickListener(v->action.run());return b;}
    private LinearLayout page(String title,Runnable back){layoutProfile=null;host.overlayOpened();colours();if(current!=null)current.dismiss();Dialog d=new Dialog(host);current=d;d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout root=column();root.setBackgroundColor(bg);root.setPadding(dp(16),dp(12),dp(16),dp(16));LinearLayout head=new LinearLayout(host);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(button("‹",()->{d.dismiss();if(back!=null)back.run();}),new LinearLayout.LayoutParams(dp(48),dp(52)));TextView name=label(title,26,text);name.setTypeface(null,Typeface.BOLD);name.setPadding(dp(12),0,0,0);head.addView(name,new LinearLayout.LayoutParams(0,-2,1));root.addView(head);LinearLayout body=column();root.addView(body,new LinearLayout.LayoutParams(-1,0,1));d.setContentView(root);d.show();d.getWindow().setBackgroundDrawableResource(android.R.color.transparent);d.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);d.getWindow().addFlags(WindowManager.LayoutParams.FLAG_DRAWS_SYSTEM_BAR_BACKGROUNDS);d.getWindow().setStatusBarColor(bg);d.getWindow().setNavigationBarColor(bg);d.getWindow().getDecorView().setSystemUiVisibility(bg==0xff000000?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);d.getWindow().setLayout(-1,-1);d.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);return body;}
    private LinearLayout scroll(LinearLayout body){ScrollView s=new ScrollView(host);s.setFillViewport(false);LinearLayout content=column();s.addView(content);body.addView(s,new LinearLayout.LayoutParams(-1,0,1));return content;}
    private View row(String title,String detail,Runnable click){LinearLayout r=new LinearLayout(host);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(12),dp(14),dp(12),dp(14));r.setMinimumHeight(dp(76));LinearLayout copy=column();TextView name=label(title,18,text);name.setTypeface(null,Typeface.BOLD);copy.addView(name);if(detail!=null&&!detail.isEmpty()){TextView sub=label(detail,14,muted);sub.setPadding(0,dp(4),0,0);copy.addView(sub);}r.addView(copy,new LinearLayout.LayoutParams(0,-2,1));if(click!=null){TextView chevron=label("›",28,accent);r.addView(chevron);r.setFocusable(true);r.setClickable(true);r.setBackground(surface(panel));r.setOnClickListener(v->click.run());}return r;}
    private void addRow(LinearLayout to,String title,String detail,Runnable action){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(5);to.addView(row(title,detail,action),p);}
    void close(){if(current!=null)current.dismiss();current=null;layoutProfile=null;handler.removeCallbacksAndMessages(null);}
